class EffectPool {
public:
  Shell* spawnShell(Vec3 pos, Vec3 vel) {
    for (int i = 0; i < MAX_SHELLS; i++) {
      if (!shells_[i].inUse()) {
        shells_[i].init(pos, vel);
        return &shells_[i];
      }
    }
    return NULL;   // pool full
  }
private:
  static const int MAX_SHELLS = 256;
  Shell shells_[MAX_SHELLS];   // allocated once, never freed
};

Sound* SoundPool::play(SoundId id, float volume) {
  Sound* slot = findFree();
  if (slot == NULL) {
    // Pool full: steal the quietest playing sound.
    slot = findQuietest();
    slot->stop();
  }
  slot->start(id, volume);
  return slot;
}

Vfx* VfxPool::spawn(...) {
  Vfx* v = findFree();
  if (v == NULL) return NULL;   // nobody will notice
  v->init(...);
  return v;
}

void Enemy::init(EnemyType* type, Vec2 pos) {
  // Fully initialize EVERY field.
  type_ = type; pos_ = pos; hp_ = type->maxHp;
  aggroTarget_ = NULL;
  statusEffects_.clear();
  inUse_ = true;
}

void Enemy::release() {
  inUse_ = false;
  aggroTarget_ = NULL;   // drop references (GC languages)
  lootTable_ = NULL;
#ifdef DEBUG
  fillDebugPattern();    // e.g. 0x1deadb0b
#endif
}

class Bullet {
public:
  Bullet* getNext() const { return state_.next; }
  void setNext(Bullet* next) { state_.next = next; }
private:
  int framesLeft_;
  union {
    struct { double x, y, vx, vy; } live;
    Bullet* next;
  } state_;
};

void BulletPool::create(double x, double y, double vx, double vy, int life) {
  assert(firstAvailable_ != NULL);
  Bullet* b = firstAvailable_;
  firstAvailable_ = b->getNext();   // read next BEFORE init overwrites it
  b->init(x, y, vx, vy, life);
}

template <class T, int N>
class Pool {
public:
  T* create() {
    for (int i = 0; i < N; i++)
      if (!inUse_[i]) { inUse_[i] = true; return &items_[i]; }
    return NULL;
  }
  void release(T* obj) { inUse_[obj - items_] = false; }
private:
  T    items_[N];
  bool inUse_[N] = {};   // state tracked outside the objects
};

